S("97", "Antihistaminika",
  "DVĚ GENERACE U JEDNÝCH DVEŘÍ DO MOZKU — stará projde a uspí, nová zůstane venku.", "pokoj",
  [("😴", "Spící postava", True, "I. GENERACE (bisulepin, prometazin, difenhydramin, hydroxyzin) prochází hematoencefalickou bariérou — SEDACE; nesmí se řídit ani pít alkohol."),
   ("🏜️", "Sucho v ústech", True, "Anticholinergní účinky: sucho v ústech, retence moči, rozmazané vidění, zácpa, u starších zmatenost."),
   ("👁️", "Glaukom", True, "Kontraindikací I. generace je glaukom s uzavřeným úhlem a hyperplazie prostaty."),
   ("🚗", "Kinetóza", False, "Sedativní a antiemetický efekt I. generace se využívá cíleně u kinetózy, nočního svědění a v premedikaci."),
   ("🧠", "Zavřená brána", False, "II. GENERACE (cetirizin, loratadin, desloratadin, fexofenadin, bilastin) do CNS prakticky nepronikají — nesedují a nemají anticholinergní efekt; volba pro denní léčbu."),
   ("💉", "Adrenalin", True, "Antihistaminika tlumí svědění, kopřivku, rýmu a kýchání, ale na ANAFYLAXI nestačí — lékem první volby je ADRENALIN i.m."),
   ("💓", "Stažené preparáty", True, "Terfenadin a astemizol byly staženy pro prodloužení QT. H2-antihistaminika (famotidin) tlumí žaludeční kyselinu.")],
  "H1-antihistaminika jsou vlastně inverzní agonisté — netlumí jen navázaný histamin, ale i bazální aktivitu receptoru.")

S("98", "Laxativa, antidiaroika",
  "DVĚ CESTY STŘEVEM — rozjet ho, nebo zastavit. A obě mají svůj zákaz.", "pokoj",
  [("💧", "Makrogol", False, "OSMOTICKÁ: makrogol váže vodu bez dráždění — dnes lék volby."),
   ("🍺", "Laktulóza", False, "Nevstřebatelný disacharid, který střevní bakterie štěpí na kyseliny; táhne vodu a SNIŽUJE VSTŘEBÁVÁNÍ AMONIAKU — proto u jaterní encefalopatie."),
   ("⚡", "Bisakodyl", True, "KONTAKTNÍ (bisakodyl, senna, pikosíran) dráždí myenterický plexus; při chronickém zneužívání hypokalemie a atonie tračníku."),
   ("🛑", "Loperamid", True, "Agonista periferních μ-receptorů, do CNS neproniká. NESMÍ se podat u DYSENTERIE a horečnatého průjmu — riziko toxického megakolon."),
   ("🥤", "Rehydratace", False, "U průjmu je zásadní perorální rehydratační roztok, nikoli zástava peristaltiky. Dále adsorbencia a probiotika."),
   ("🚫", "Zákaz u obstrukce", True, "Laxativa se nepodávají při podezření na střevní obstrukci nebo náhlou příhodu břišní."),
   ("🌾", "Psyllium", False, "Objemová laxativa vyžadují dostatečný příjem tekutin; parafinový olej zhoršuje vstřebávání vitaminů rozpustných v tucích; methylnaltrexon a naloxegol na zácpu při opioidech.")],
  "Základem léčby zácpy zůstává vláknina, tekutiny a pohyb — laxativum se nasazuje až po vyloučení organické příčiny.")

S("99", "Farmakoterapie vředové choroby a GERD",
  "VÁHY NAD ŽALUDKEM — na jedné straně kyselina, pepsin, H. pylori a NSA, na druhé hlen a prostaglandiny.", "pokoj",
  [("⚖️", "Váhy", False, "Vřed vzniká nepoměrem mezi agresivními faktory a ochranou sliznice. Léčba tlumí kyselinu, eradikuje bakterii a odstraní vyvolávající lék."),
   ("🔒", "Protonová pumpa", False, "IPP (omeprazol, pantoprazol, esomeprazol) ireverzibilně blokují H+/K+-ATPázu — poslední společný krok sekrece, proto nejúčinnější."),
   ("🍳", "Nalačno", True, "Aktivují se jen na sekretující pumpě — podávají se 30 minut PŘED jídlem, jinak nezaberou."),
   ("💊", "Klopidogrel", True, "Omeprazol inhibuje CYP2C19 a snižuje účinek klopidogrelu — volí se pantoprazol. Dlouhodobě hypomagnezemie, deficit B12, klostridiová kolitida, zlomeniny."),
   ("🦠", "Eradikace", False, "IPP + amoxicilin + klarithromycin (nebo metronidazol), běžně jako čtyřkombinace s bismutem, 10–14 dní."),
   ("🧪", "Antacida", True, "Neutralizují rychle, ale krátce a VÁŽOU jiná léčiva — podávat s odstupem."),
   ("🤰", "Misoprostol", True, "Analog prostaglandinu chrání před NSA, ale je kontraindikován v graviditě. Sukralfát tvoří film na spodině vředu.")],
  "Vřed po NSA může krvácet bez varovné bolesti, protože NSA bolest tlumí — proto se u rizikových podává IPP profylakticky.")

S("100", "Prokinetika, antiemetika, emetika",
  "TŘI RŮZNÉ PŘÍČINY ZVRACENÍ — a ke každé jiný lék. Univerzální antiemetikum neexistuje.", "pokoj",
  [("🚀", "Prokinetikum", False, "Metoklopramid (antagonista D2), itoprid, domperidon (do CNS proniká málo, ale prodlužuje QT) urychlují vyprazdňování žaludku a zvyšují tonus dolního jícnového svěrače."),
   ("🤖", "Dystonie", True, "METOKLOPRAMID prochází do CNS — akutní dystonie a po delším podávání tardivní dyskineze; odtud omezení dávky i délky a zákaz u parkinsonika."),
   ("🎯", "Ondansetron", False, "Setrony blokují 5-HT3 v area postrema a ve střevě — základ u zvracení po cytostatikách, ozáření a po operaci. Zácpa, bolest hlavy, prodloužení QT."),
   ("💊", "Aprepitant", False, "Antagonista NK1 proti pozdní fázi po chemoterapii; kortikosteroidy (dexametazon) v kombinaci."),
   ("🚗", "Kinetóza", False, "Antihistaminika I. generace (prometazin) a anticholinergika (skopolamin)."),
   ("🕯️", "Paliativní péče", False, "Neuroleptika (haloperidol, levomepromazin); kanabinoidy rezervně."),
   ("🚫", "Emetika", True, "Ipekakuanha a apomorfin se dnes při otravách prakticky nepoužívají — vyvolávat zvracení se nedoporučuje pro riziko aspirace.")],
  "Erythromycin působí přes motilinový receptor a používá se jako prokinetikum u gastroparézy — antibiotikum v nemikrobiální indikaci.")

S("101", "Farmakoterapie nespecifických střevních zánětů",
  "DVĚ FÁZE JEDNÉ LÉČBY — navodit remisi a udržet ji. Kortikoid patří jen do první.", "pokoj",
  [("🎯", "Navození remise", False, "Kortikosteroidy (prednison; u ileocékální lokalizace BUDESONID s vysokým first-pass efektem, a tedy nižší systémovou toxicitou) rychle potlačí aktivitu."),
   ("⛔", "Zákaz dlouhodobě", True, "Kortikoidy se k UDRŽENÍ remise nikdy nepoužívají — pro nežádoucí účinky."),
   ("🔒", "Azathioprin", True, "Azathioprin a 6-merkaptopurin udržují remisi; před nasazením se vyšetřuje aktivita TPMT kvůli riziku myelosuprese. Dále metotrexát."),
   ("🌿", "Mesalazin", False, "5-ASA se uvolňuje v tlustém střevě a působí lokálně protizánětlivě — základ u ULCERÓZNÍ KOLITIDY, u Crohnovy nemoci malý účinek."),
   ("💊", "Sulfasalazin", True, "Způsobuje nauzeu, vyrážku a reverzibilní oligospermii."),
   ("🦠", "Latentní tuberkulóza", True, "Před anti-TNF-α (infliximab, adalimumab) je nutné vyloučit latentní tuberkulózu a hepatitidu B — hrozí reaktivace."),
   ("🎯", "Vedolizumab", False, "Anti-integrin, střevně selektivní; dále ustekinumab (anti-IL-12/23) a inhibitory JAK.")],
  "Crohnova nemoc a ulcerózní kolitida se léčí odlišně — mesalazin je účinný hlavně u kolitidy, u Crohnovy nemoci se dřív sahá po imunosupresi a biologikách.")

S("102", "Spasmolytika",
  "DVĚ CESTY K UVOLNĚNÍ KŘEČE — přerušit povel, nebo působit rovnou na sval.", "pokoj",
  [("🧠", "Přerušený povel", False, "NEUROTROPNÍ — butylskopolamin blokuje muskarinové receptory hladkého svalu."),
   ("🚪", "Kvartérní amin", False, "Butylskopolamin je kvartérní amin — NEPROCHÁZÍ hematoencefalickou bariérou, takže neseduje."),
   ("🏜️", "Anticholinergní obtíže", True, "Sucho v ústech, rozmazané vidění, tachykardie, retence moči, zácpa. Kontraindikace: glaukom s uzavřeným úhlem, hyperplazie prostaty, tachyarytmie, paralytický ileus."),
   ("💪", "Přímo na sval", False, "MYOTROPNÍ — drotaverin a papaverin inhibují fosfodiesterázu, zvyšují cAMP a přímo relaxují sval; nemají anticholinergní nežádoucí účinky."),
   ("👁️", "Volba u glaukomu", False, "Proto jsou myotropní vhodnější u pacienta s glaukomem nebo prostatismem."),
   ("🌀", "Metamizol", True, "Má vlastní spasmolytickou složku — hodí se u ledvinné a žlučníkové koliky; riziko agranulocytózy a hypotenze při rychlém i.v. podání."),
   ("🌿", "Dráždivý tračník", False, "Mebeverin, pinaveriumbromid (blokátor kalciových kanálů střeva) a peprmintový olej.")],
  "Spasmolytikum tlumí viscerální bolest tím, že odstraní její příčinu — proto u koliky často funguje lépe než čisté analgetikum.")

S("103", "Hepatoprotektiva, cholagoga",
  "JÁTRA, KTERÁ NEJVÍC POMŮŽE VYSAZENÍ — u většiny „hepatoprotektiv“ je důkaz slabý.", "les",
  [("🍀", "Ostropestřec", False, "SILYMARIN působí antioxidačně a stabilizuje membránu hepatocytu; jedinou doloženou indikací je otrava muchomůrkou zelenou, kde silibinin i.v. brání vstupu amanitinu do buňky."),
   ("💊", "N-acetylcystein", False, "Doplňuje glutathion — antidotum otravy paracetamolem."),
   ("🟡", "UDCA", False, "Kyselina ursodeoxycholová je hydrofilní žlučová kyselina nahrazující toxické — lék volby u primární biliární cholangitidy; rozpouští drobné cholesterolové konkrementy."),
   ("⛔", "Obstrukce", True, "Cholagoga (choleretika zvyšují tvorbu žluči, cholekinetika vyprazdňování žlučníku) jsou KONTRAINDIKOVÁNA při obstrukci žlučových cest."),
   ("🧠", "Encefalopatie", False, "Ornithin-aspartát a laktulóza snižují amoniak; rifaximin snižuje jeho střevní produkci."),
   ("🍺", "Alkohol", True, "Nejúčinnějším hepatoprotektivem je vysazení alkoholu a hepatotoxického léku, léčba viru a redukce hmotnosti u steatózy."),
   ("❓", "Esenciální fosfolipidy", False, "Používají se u steatózy, důkazy o účinnosti jsou slabé.")],
  "Silymarin se běžně užívá jako doplněk stravy — a právě proto se na něj v anamnéze nezapomíná ptát; jeho doložená role je jen u otravy amanitinem.")

S("104", "Farmaka v očním lékařství",
  "OČNÍ ORDINACE S ODTOKEM — kapka do oka odteče nosem do celého těla.", "pokoj",
  [("💧", "Slzný bod", True, "Část léčiva se vstřebá spojivkou a nosní sliznicí — proto i kapky mají systémové účinky. Vstřebávání sníží stlačení slzného bodu po nakapání."),
   ("🌿", "Latanoprost", False, "Analoga prostaglandinů zvyšují uveosklerální ODTOK komorové vody — PRVNÍ VOLBA u glaukomu. Barví duhovku a prodlužují řasy."),
   ("🫁", "Timolol", True, "β-blokátor snižuje TVORBU komorové vody; kontraindikací je astma, CHOPN a bradykardie."),
   ("💊", "Dorzolamid", False, "Inhibitory karboanhydrázy (dorzolamid lokálně, acetazolamid celkově) a α2-agonisté (brimonidin)."),
   ("👁️", "Pilokarpin", False, "Parasympatomimetikum — mióza, otevře úhel; u akutního záchvatu glaukomu s uzavřeným úhlem."),
   ("⛔", "Mydriatika", True, "Tropikamid, atropin a fenylefrin k vyšetření očního pozadí — KONTRAINDIKOVANÉ u glaukomu s uzavřeným úhlem."),
   ("⚠️", "Kortikoid v oku", True, "Tlumí zánět, ale zvyšuje nitrooční tlak, urychluje KATARAKTU a zhoršuje herpetickou keratitidu. Anti-VEGF (ranibizumab, aflibercept) intravitreálně u vlhké makulární degenerace.")],
  "Glaukom s otevřeným a s uzavřeným úhlem mají odlišnou léčbu — pilokarpin je určen k otevření úhlu při akutním záchvatu, ne k dlouhodobé léčbě otevřeného glaukomu.")

S("105", "Drogová (léková) závislost",
  "JEDNA CESTA PRO VŠECHNY DROGY — dopamin do nucleus accumbens. A odvykací stav je jejím zrcadlem.", "noc",
  [("🧠", "Dopaminová dráha", False, "Ventrální tegmentum → nucleus accumbens; všechny návykové látky přímo či nepřímo zvyšují dopamin, což upevňuje chování."),
   ("💭", "Craving", True, "Psychická závislost (bažení, ztráta kontroly) je nejhůř léčitelná. Kritéria: craving, ztráta kontroly, tolerance, odvykací stav, zanedbávání zájmů, pokračování přes následky."),
   ("🪞", "Zrcadlo", False, "Odvykací stav bývá ZRCADLEM účinku látky: po opioidech (mióza, zácpa, útlum) přijde mydriáza, průjem, slzení a bolesti."),
   ("☠️", "Delirium tremens", True, "Odvykací stav po ALKOHOLU a BENZODIAZEPINECH může vyústit v epileptické záchvaty a delirium tremens — je ŽIVOT OHROŽUJÍCÍ; léčí se benzodiazepiny."),
   ("📉", "Tolerance", False, "Pokles účinku při opakovaném podání — farmakodynamická nebo metabolická; zkřížená tolerance mezi látkami stejného mechanismu (alkohol, benzodiazepiny, barbituráty)."),
   ("🔄", "Substituce", False, "Metadon, buprenorfin, nikotinové náhrady."),
   ("🛡️", "Snížení cravingu", False, "Naltrexon, akamprosát, vareniklin; averzivně disulfiram. Základem zůstává psychoterapie.")],
  "Odvykání od opioidů je nepříjemné, ale samo o sobě obvykle neohrožuje život — na rozdíl od odvykání od alkoholu a benzodiazepinů.")

S("106", "Ethylalkohol, methylalkohol",
  "DVĚ LÁHVE, JEDEN ENZYM — methanol sám neškodí, zabíjejí jeho metabolity. Proto se enzymu podstrčí ethanol.", "pokoj",
  [("🍺", "Láhev ethanolu", False, "Potencuje GABA-A a inhibuje NMDA. Odbourává se alkoholdehydrogenázou na acetaldehyd a dále na acetát; kinetikou NULTÉHO ŘÁDU (0,1–0,15 ‰/h) — rychlost nelze urychlit. Chronicky CYP2E1 (indukce → tolerance)."),
   ("🧠", "Thiamin", True, "U alkoholika se thiamin podává VŽDY PŘED GLUKÓZOU — jinak se vyprovokuje Wernickeova encefalopatie (zmatenost, ataxie, oftalmoplegie) až Korsakovův syndrom."),
   ("🫀", "Orgánové škody", True, "Hypoglykemie, steatóza → hepatitida → cirhóza, pankreatitida, kardiomyopatie, polyneuropatie, fetální alkoholový syndrom."),
   ("👁️", "Slepota", True, "METHANOL se alkoholdehydrogenázou mění na FORMALDEHYD a KYSELINU MRAVENČÍ — těžká metabolická acidóza a poškození očního nervu se slepotou; latence několik hodin."),
   ("💊", "Fomepizol", True, "Antidotum: kompetiční blokáda tvorby metabolitů — FOMEPIZOL nebo ETHANOL; dále hemodialýza, bikarbonát a kyselina listová."),
   ("🧊", "Ethylenglykol", True, "Stejný princip — oxalátové krystaly a selhání ledvin."),
   ("🌀", "Delirium tremens", True, "Odvykací stav se léčí benzodiazepiny.")],
  "Léčit methanolovou otravu ethanolem není paradox: obě látky soupeří o týž enzym, a dokud ho ethanol obsazuje, methanol se na toxické metabolity nepřemění.")

S("107", "Konopí, kanabinoidy",
  "MOZEK PLNÝ CB1, ALE PRODLOUŽENÁ MÍCHA PRÁZDNÁ — proto konopí netlumí dech.", "les",
  [("🧠", "CB1 v mozku", False, "CB1 je hojný v bazálních gangliích, hipokampu, mozečku a kůře — odtud psychotropní účinky. CB2 je na buňkách imunitního systému."),
   ("🫁", "Prázdná prodloužená mícha", True, "V prodloužené míše se CB1 prakticky nevyskytuje — proto konopí NETLUMÍ dechové centrum, na rozdíl od opioidů."),
   ("🌀", "THC", False, "Delta-9-tetrahydrocannabinol je parciální agonista CB1; kanabidiol (CBD) psychoaktivní není."),
   ("👁️", "Rudé spojivky", False, "Euforie, změněné vnímání času, poruchy krátkodobé paměti a pozornosti, zhoršená koordinace (riziko při řízení), tachykardie, překrvení spojivek, sucho v ústech, zvýšená chuť k jídlu."),
   ("😰", "Psychóza", True, "Ve vyšších dávkách úzkost, panika, u disponovaných psychotická ataka; užívání v dospívání zvyšuje riziko schizofrenie. Vzniká psychická závislost a amotivační syndrom."),
   ("🤮", "Hyperemetický syndrom", True, "Kanabinoidní hyperemetický syndrom při chronickém užívání."),
   ("💊", "Léčebné využití", False, "Nabiximols (THC/CBD) u spasticity u roztroušené sklerózy; dronabinol a nabilon proti zvracení po chemoterapii a při kachexii; kanabidiol u farmakorezistentní epilepsie (Dravetové, Lennoxův–Gastautův syndrom).")],
  "Kanabidiol není „slabší THC“ — nemá psychotropní účinek a má vlastní antikonvulzivní a anxiolytické působení, proto má i vlastní indikace.")

S("108", "Halucinogeny (psychomimetika)",
  "TŘI RŮZNÉ SVĚTY — serotonergní, disociativní a anticholinergní. Jen jeden z nich má antidotum.", "noc",
  [("🌈", "LSD", False, "SEROTONERGNÍ: LSD, psilocybin, meskalin, DMT jsou agonisté 5-HT2A. Mydriáza, tachykardie, hypertenze, hypertermie. Rychlá tolerance, ale NEVYVOLÁVAJÍ fyzickou závislost."),
   ("😱", "Bad trip", True, "Panika a paranoia — zvládá se klidným prostředím a benzodiazepiny; dále flashbacky (HPPD) a u disponovaných spuštění psychózy."),
   ("🌀", "Ketamin a PCP", False, "DISOCIATIVNÍ: antagonisté NMDA — pocit odloučení od těla, analgezie, amnézie. PCP navíc agresivita, hypertenze a nystagmus."),
   ("💊", "Terapeutický ketamin", False, "Používá se jako anestetikum a (esketamin) u farmakorezistentní deprese."),
   ("🥀", "Durman a rulík", True, "ANTICHOLINERGNÍ: atropin, skopolamin a rostliny rulík, durman, blín — DELIRIUM: mydriáza, suchá horká červená kůže, tachykardie, retence moči."),
   ("💉", "Fysostigmin", True, "Antidotum anticholinergního deliria — jediná ze tří skupin, která ho má."),
   ("🔥", "MDMA", True, "Masivně uvolňuje serotonin — hypertermie, hyponatremie (z nadměrného pití vody) a serotoninový syndrom.")],
  "Rozlišení skupin má praktický dopad: anticholinergní delirium se léčí fysostigminem, kdežto serotonergní „bad trip“ se jen tlumí benzodiazepinem.")

S("109", "Stimulancia",
  "ZÁVOD BEZ BRZD — dopamin a noradrenalin nahoru, a u kokainu ⚠️ žádné betablokátory.", "noc",
  [("⬆️", "Vzestup", False, "Amfetamin a metamfetamin (pervitin) obracejí chod transportérů a vyplavují katecholaminy; kokain blokuje jejich zpětné vychytávání."),
   ("👃", "Nekróza přepážky", True, "Kokain je zároveň lokálním anestetikem (blokáda sodíkových kanálů) — vazokonstrikce s nekrózou nosní přepážky a riziko infarktu při koronárním spasmu."),
   ("⛔", "Zákaz β-blokátoru", True, "U kokainové kardiotoxicity se β-blokátory NEPODÁVAJÍ — nebrzděná α-stimulace by spasmus prohloubila. Volí se benzodiazepiny, nitráty a blokátory kalciových kanálů."),
   ("😵", "Toxická psychóza", True, "Chronicky paranoia a halucinace (léčí se antipsychotiky), kachexie, poškození chrupu a silná psychická závislost s těžkým „dojezdem“ (deprese, hypersomnie)."),
   ("🔥", "Předávkování", True, "Hypertermie, arytmie, infarkt, cévní mozková příhoda a křeče."),
   ("🧒", "ADHD", False, "Metylfenidát, lisdexamfetamin a atomoxetin (inhibitor zpětného vychytávání noradrenalinu, nenávykový)."),
   ("☕", "Modafinil a kofein", False, "Modafinil u narkolepsie; do skupiny patří i kofein a efedrin.")],
  "Metylfenidát u ADHD nepůsobí paradoxně — zvýšení dopaminu a noradrenalinu v prefrontální kůře zlepší schopnost útlumu a soustředění.")

S("110", "Nikotin",
  "CIGARETA SE DVĚMA ÚČTY — nikotin dělá závislost, dehet a oxid uhelnatý dělají nemoci.", "noc",
  [("🚬", "Receptor α4β2", False, "Nikotin je agonista nikotinových acetylcholinových receptorů, v CNS zejména α4β2; jejich aktivace vede k výlevu dopaminu v nucleus accumbens."),
   ("⏱️", "Sekundy do mozku", True, "Vstřebává se plícemi a mozku dosáhne během sekund — proto je návykový potenciál srovnatelný s heroinem."),
   ("⚫", "Dehet a CO", True, "Za většinu zdravotních škod kouření (nádory, CHOPN, ateroskleróza) odpovídá dehet a oxid uhelnatý, NIKOLI nikotin sám."),
   ("🏭", "Indukce CYP1A2", True, "Kouření snižuje hladiny theofylinu, klozapinu a olanzapinu; po zanechání kouření je nutné dávky upravit."),
   ("👶", "Otrava dítěte", True, "Ve vysokých dávkách depolarizační blokáda ganglií s křečemi, zvracením a zástavou dechu — akutní otrava po požití cigaret nebo náplně e-cigarety."),
   ("💊", "Vareniklin", False, "Parciální agonista α4β2 — tlumí craving a zároveň blokuje odměnu z cigarety."),
   ("⚡", "Bupropion", True, "Inhibitor zpětného vychytávání dopaminu a noradrenalinu; snižuje práh křečí. Dále nikotinová substituce (náplasti, žvýkačky, pastilky).")],
  "Odvykací stav: neodolatelná touha kouřit, podrážděnost, úzkost, nesoustředěnost, zvýšená chuť k jídlu a přírůstek hmotnosti.")

S("111", "Metylxantiny a jejich deriváty",
  "KAVÁRNA S ÚZKÝM PRŮCHODEM — adenosin je zablokovaný, ale theofylin má úzké okno.", "pokoj",
  [("☕", "Šálek kávy", False, "Kofein, theofylin a theobromin jsou purinové alkaloidy. ANTAGONISMUS ADENOSINOVÝCH receptorů vysvětluje bdělost — adenosin je látka útlumu a spánku."),
   ("🫁", "Bronchodilatace", False, "Ve vyšších koncentracích inhibice FOSFODIESTERÁZY, vzestup cAMP — bronchodilatace a stimulace srdce; dále mírná diuréza a zvýšení žaludeční sekrece."),
   ("📏", "Úzké okno", True, "THEOFYLIN je antiastmatikum druhé volby s úzkým terapeutickým oknem — nutná monitorace hladin; předávkování se projeví arytmiemi a křečemi."),
   ("🚬", "Kouření snižuje", True, "Metabolizuje se CYP1A2 — kouření hladinu SNIŽUJE (indukce)."),
   ("💊", "Makrolidy zvyšují", True, "Erythromycin, klarithromycin, ciprofloxacin, fluvoxamin a srdeční selhání hladinu ZVYŠUJÍ."),
   ("👶", "Apnoe nedonošených", False, "Kofein se terapeuticky používá u apnoe nedonošených, s analgetiky zesiluje jejich účinek a u postpunkční bolesti hlavy."),
   ("🦵", "Pentoxifylin", False, "Zlepšuje deformabilitu erytrocytů u ischemické choroby dolních končetin.")],
  "Adenosin se používá jako antiarytmikum — a u pacienta po kávě může být méně účinný, protože kofein jeho receptory blokuje.")

S("112", "Antirevmatika",
  "DVĚ PATRA LÉČBY — dole úleva, nahoře záchrana kloubu. A metotrexát jen JEDNOU TÝDNĚ.", "pokoj",
  [("💊", "NSA a kortikoid", True, "Tlumí bolest, otok a ranní ztuhlost, ale PRŮBĚH NEMOCI NEZMĚNÍ. Kortikoid slouží jako „most“, než začnou působit DMARDs."),
   ("🛡️", "DMARDs", False, "Chorobu modifikující léčiva zpomalují destrukci kloubu — nasazují se co nejdříve po stanovení diagnózy."),
   ("📅", "Jednou týdně", True, "METOTREXÁT je lékem první volby u revmatoidní artritidy a podává se JEDNOU TÝDNĚ — denní podání je závažná chyba s rizikem úmrtí; doplňuje se kyselinou listovou."),
   ("🤰", "Kontraindikace", True, "Metotrexát je hepatotoxický, myelotoxický a v graviditě kontraindikovaný."),
   ("👁️", "Hydroxychlorochin", True, "Retinopatie — nutné oční kontroly. Dále leflunomid a sulfasalazin."),
   ("🦠", "Před biologiky", True, "Anti-TNF-α (infliximab, adalimumab, etanercept), rituximab, tocilizumab, abatacept — před nasazením vyloučit latentní tuberkulózu a hepatitidu B; obecně zvyšují riziko infekcí."),
   ("🩸", "Inhibitory JAK", True, "Tofacitinib, baricitinib — pozor na trombembolie a kardiovaskulární riziko.")],
  "Bolest může být pod kontrolou i při pokračující destrukci kloubu — proto se úspěch léčby neposuzuje jen podle úlevy, ale podle aktivity nemoci.")

S("113", "Antiuratika",
  "DVĚ ZCELA ODDĚLENÉ LÉČBY — hasit požár a stavět protipožární zeď. Nikdy obojí najednou.", "poust",
  [("🔥", "Hašení záchvatu", False, "NSA (indometacin, naproxen), KOLCHICIN (blokuje polymeraci mikrotubulů, a tím migraci neutrofilů; limitující je průjem) a kortikosteroidy systémově nebo do kloubu."),
   ("🚫", "Ne aspirin", True, "Kyselina acetylsalicylová se u dny nepodává — v nízké dávce retenci urátů ZHORŠUJE."),
   ("⛔", "Zákaz zahájení", True, "Během akutního záchvatu se hypourikemická léčba NEZAHAJUJE — každá změna urikemie záchvat prodlužuje. Pokud ji pacient už užívá, NEVYSAZUJE se."),
   ("🏭", "Allopurinol", False, "Inhibuje XANTHINOXIDÁZU, a snižuje tak tvorbu kyseliny močové; lék volby. Zahajuje se nízkou dávkou pod clonou kolchicinu nebo NSA."),
   ("🔴", "Hypersenzitivita", True, "Vyrážka až závažný hypersenzitivní syndrom (riziko u HLA-B*5801). Febuxostat je alternativou."),
   ("🩸", "Azathioprin", True, "Allopurinol blokuje odbourávání azathioprinu a 6-merkaptopurinu — hrozí těžká myelosuprese."),
   ("💧", "Probenecid", True, "Urikosurikum zvyšuje vylučování urátů; nesmí se podat při urátové nefrolitiáze a vyžaduje dostatečný příjem tekutin. Rasburikáza u syndromu nádorového rozpadu.")],
  "Bezpříznaková hyperurikemie se sama o sobě neléčí — indikací jsou opakované záchvaty, tofy, urátová nefropatie nebo litiáza.")

S("114", "Imunosupresiva, imunostimulancia",
  "ZTIŠENÁ POSÁDKA HRADU — když se imunita utlumí, dovnitř se dostane infekce i nádor.", "hory",
  [("🦠", "Otevřená brána", True, "Společným rizikem VŠECH imunosupresiv je infekce a zvýšený výskyt nádorů — proto se kombinují v nižších dávkách."),
   ("🫘", "Kalcineurin", True, "Cyklosporin A a takrolimus blokují tvorbu interleukinu-2 v T-lymfocytu; základ transplantační imunosuprese. NEFROTOXICITA a úzké terapeutické okno — nutná monitorace hladin."),
   ("🍇", "CYP3A4", True, "Metabolizují se CYP3A4 — interakce s azoly, makrolidy a grapefruitem."),
   ("🦷", "Gingivální hyperplazie", True, "Cyklosporin navíc hypertenze, hirsutismus a gingivální hyperplazie; takrolimus je neurotoxický a diabetogenní."),
   ("🧬", "Azathioprin a TPMT", True, "Před nasazením se vyšetřuje TPMT. Mykofenolát mofetil blokuje syntézu purinů v lymfocytech a je teratogenní."),
   ("🩹", "Inhibitory mTOR", False, "Sirolimus, everolimus — nefrotoxické nejsou, ale zhoršují hojení a působí dyslipidemii."),
   ("⬆️", "Imunostimulancia", True, "Interferony (α u hepatitid, β u roztroušené sklerózy), filgrastim (G-CSF), bakteriální lyzáty a inhibitory kontrolních bodů (nivolumab, pembrolizumab) — jejich typickým nežádoucím účinkem jsou AUTOIMUNITNÍ reakce.")],
  "Inhibitory kontrolních bodů jsou opakem imunosuprese — uvolňují brzdu imunity, a proto jejich nežádoucí účinky vypadají jako autoimunitní onemocnění.")

S("115", "Hormony hypothalamu, hypofýzy, jejich analoga",
  "TÝŽ HORMON, DVA OPAČNÉ VÝSLEDKY — pulzně stimuluje, trvale utlumí.", "laborator",
  [("⏱️", "Pulzní dávkování", False, "Pulzní podání GnRH napodobuje fyziologii a osu STIMULUJE — používá se v léčbě neplodnosti."),
   ("🔇", "Trvalé podání", False, "Depotní analoga GnRH (goserelin, leuprorelin, triptorelin) receptory DESENZITIZUJÍ a navodí chemickou kastraci — karcinom prostaty a prsu, endometrióza, myomy, předčasná puberta."),
   ("🔥", "Flare-up", True, "Na začátku dojde k přechodnému vzplanutí sekrece — u karcinomu prostaty se kryje antiandrogenem. Antagonisté GnRH (degarelix, cetrorelix) tlumí ihned, bez vzplanutí."),
   ("🍼", "Prolaktin", True, "Tlumí se AGONISTY DOPAMINU (kabergolin, bromokriptin), protože dopamin je fyziologickým inhibitorem prolaktinu — prolaktinom, potlačení laktace."),
   ("📏", "Oktreotid", False, "Somatostatinová analoga tlumí růstový hormon — akromegalie, neuroendokrinní nádory, krvácení z jícnových varixů. Pegvisomant je antagonista receptoru pro GH; somatropin při nedostatku GH u dětí."),
   ("🤰", "Oxytocin", False, "Vyvolává děložní kontrakce — indukce porodu, poporodní atonie."),
   ("💧", "Desmopresin", False, "Vasopresin a desmopresin působí antidiureticky (diabetes insipidus, noční pomočování, hemofilie A a von Willebrandova choroba); terlipresin u krvácení z varixů; tolvaptan u hyponatremie.")],
  "Metoklopramid a antipsychotika blokují D2 receptory, a tím zvyšují prolaktin — odtud galaktorea, amenorea a gynekomastie při jejich užívání.")

S("116", "Farmakoterapie onemocnění štítné žlázy",
  "SNÍDANĚ, KTERÁ MUSÍ POČKAT — levotyroxin nalačno, a tyreostatika zaberou až za týdny.", "pokoj",
  [("🍽️", "Prázdný talíř", True, "Levotyroxin se podává jednou denně NALAČNO, 30–60 minut před snídaní; potrava, ŽELEZO, VÁPNÍK, antacida a inhibitory protonové pumpy zhoršují jeho vstřebávání."),
   ("🔄", "T4 na T3", False, "T4 je proléčivo dejodované v tkáních na účinnější T3 — to zajišťuje stabilní hladinu. TSH je hlavním ukazatelem úspěšnosti léčby."),
   ("🐢", "Opatrný start", True, "U starších a u ischemické choroby srdeční se začíná nízkou dávkou — jinak hrozí vyprovokování anginy nebo arytmie. Předávkování se projeví jako tyreotoxikóza."),
   ("🤰", "Gravidita", False, "V graviditě potřeba levotyroxinu stoupá."),
   ("⏳", "Zpoždění tyreostatik", True, "Thiamazol a propylthiouracil inhibují tyreoidální peroxidázu; účinek nastupuje se zpožděním TÝDNŮ, protože se musí vyčerpat zásoba hormonu ve žláze."),
   ("🩸", "Agranulocytóza", True, "Nejzávažnější nežádoucí účinek tyreostatik — při horečce a angíně okamžitě vyšetřit krevní obraz. Dále hepatotoxicita."),
   ("☢️", "Radiojod", True, "131I ničí tkáň žlázy a je kontraindikován v graviditě. Propylthiouracil blokuje i periferní konverzi T4 na T3 — volba v prvním trimestru a u tyreotoxické krize; β-blokátory rychle tlumí příznaky.")],
  "Amiodaron obsahuje jod a může vyvolat hypotyreózu i hypertyreózu — proto se u něj funkce štítné žlázy pravidelně kontroluje.")

S("117", "Glukokortikoidy, mineralokortikoidy",
  "DŮM, KTERÝ SE NESMÍ OPUSTIT NÁHLE — po dvou týdnech je osa utlumená a náhlé vysazení znamená krizi.", "pokoj",
  [("🧬", "Přepis genů", False, "Kortikosteroidy se vážou na nitrobuněčný receptor a mění přepis genů — odtud pomalý nástup. Potlačují fosfolipázu A2, tvorbu cytokinů a migraci leukocytů."),
   ("🎭", "Cushingova tvář", True, "Nežádoucí účinky odpovídají Cushingovu syndromu: hyperglykemie až steroidní diabetes, centrální obezita, svalová atrofie, ztenčení kůže a špatné hojení."),
   ("🦴", "Osteoporóza", True, "Prevence vápníkem a vitaminem D; dále katarakta a glaukom, hypertenze, psychické změny a potlačení růstu u dětí."),
   ("🕳️", "Vřed s NSA", True, "Riziko žaludečního vředu stoupá zvláště v kombinaci s NSA."),
   ("⛔", "Zákaz náhlého vysazení", True, "Při podávání delším než dva týdny se osa hypothalamus–hypofýza–nadledviny utlumí — náhlé vysazení vede k AKUTNÍ ADRENÁLNÍ INSUFICIENCI. Vysazuje se postupně."),
   ("📈", "Zátěžová dávka", True, "Při operaci, infekci nebo úrazu se dávka NAVYŠUJE — utlumená nadledvina nedokáže odpovědět sama."),
   ("🧂", "Fludrokortison", False, "Mineralokortikoidy zvyšují zpětné vstřebávání sodíku a vylučování draslíku — u Addisonovy nemoci; nadbytek působí hypertenzi, hypokalemii a metabolickou alkalózu.")],
  "Inhalační a lokální formy mají nižší systémové riziko, ale ve vysokých dávkách osu utlumí také — proto se i u nich hlídá kumulativní dávka.")

S("118", "Farmakoterapie obezity",
  "VÁHA S CEDULÍ „JEN DOPLNĚK“ — lék nikdy nenahradí stravu a pohyb.", "pokoj",
  [("📊", "Váha s číslem", False, "Indikace zpravidla při BMI ≥ 30, nebo BMI ≥ 27 s přidruženým onemocněním (diabetes 2. typu, hypertenze, spánková apnoe)."),
   ("💉", "GLP-1 agonisté", False, "Liraglutid, semaglutid a duální agonista GIP/GLP-1 tirzepatid zpomalují vyprazdňování žaludku, zvyšují sytost a působí centrálně — největší pokles hmotnosti, zlepšení glykemie i kardiovaskulární prognózy."),
   ("🤢", "Nauzea", True, "Nauzea, zvracení a průjem — proto se dávka pomalu titruje; dále riziko pankreatitidy a cholelitiázy."),
   ("🦋", "MEN2", True, "Kontraindikací je medulární karcinom štítné žlázy a syndrom MEN2 v anamnéze."),
   ("🧈", "Orlistat", False, "Inhibuje střevní a pankreatickou lipázu — brání vstřebání zhruba třetiny tuku; působí jen v lumen střeva."),
   ("🚽", "Steatorea", True, "Nežádoucí účinky plynou přímo z mechanismu: steatorea, plynatost, urgence a únik stolice. ZHORŠUJE vstřebávání vitaminů A, D, E, K — nutná substituce s odstupem."),
   ("⚕️", "Bariatrie", False, "Naltrexon/bupropion působí centrálně. Sibutramin a fenfluramin byly staženy pro kardiovaskulární rizika. Nejúčinnějším postupem u těžké obezity zůstává bariatrická operace.")],
  "Po vysazení farmakoterapie se hmotnost zpravidla vrací — obezita je chronické onemocnění, proto se léčba plánuje jako dlouhodobá, ne jako kúra.")

S("119", "Androgeny, anabolické steroidy",
  "POSILOVNA SE DVĚMA PŘEMĚNAMI — testosteron se mění na silnější DHT a zároveň na ESTROGEN.", "pokoj",
  [("🔀", "Dvojí přeměna", False, "5-α-reduktázou na účinnější DIHYDROTESTOSTERON, aromatázou na estradiol. Účinky androgenní (mužské znaky, spermatogeneze) a anabolické (svalová hmota, kostní denzita, erytropoéza)."),
   ("🍒", "Gynekomastie", True, "Vzniká přeměnou androgenu na estrogeny — proto se objevuje i u mužů na vysokých dávkách."),
   ("🔻", "Atrofie varlat", True, "Zpětnou vazbou se tlumí osa hypothalamus–hypofýza–varle: atrofie varlat, pokles spermiogeneze a neplodnost."),
   ("🩸", "Polyglobulie", True, "Riziko trombózy; dále akné, retence sodíku a vody, dyslipidemie a růst prostaty. Kontraindikací je karcinom prostaty a prsu a gravidita."),
   ("🗣️", "Prohloubený hlas", True, "U žen NEVRATNÉ prohloubení hlasu, hirsutismus a klitoromegalie; u dospívajících předčasný uzávěr růstových štěrbin."),
   ("💊", "Hepatotoxicita", True, "Perorální 17-α-alkylované deriváty jsou hepatotoxické — substituce se podává injekčně nebo transdermálně."),
   ("🏅", "Doping", True, "Anabolické steroidy (nandrolon, stanozolol, oxandrolon) zneužívané ve sportu v mnohonásobných dávkách — hepatotoxicita, agresivita, kardiomyopatie. Antiandrogeny: flutamid, bikalutamid, cyproteron, finasterid, spironolakton.")],
  "Finasterid a dutasterid blokují právě 5-α-reduktázu — proto snižují DHT (prostata, vlasy), ale testosteron ponechávají.")

S("120", "Estrogeny, gestageny",
  "DĚLOHA BEZ OCHRANY — estrogen sám znamená nebrzděnou proliferaci endometria.", "pokoj",
  [("🚫", "Estrogen samotný", True, "U ženy s DĚLOHOU se estrogen nikdy nepodává sám — hyperplazie až karcinom endometria. Po hysterektomii lze."),
   ("🩸", "Trombembolie", True, "Hlavní riziko estrogenů; dále zvýšené riziko karcinomu prsu při dlouhodobé kombinované HRT, cévní mozková příhoda, cholelitiáza, hypertenze."),
   ("🦴", "Ochrana kosti", False, "Estrogeny tlumí osteoklasty a udržují kostní hmotu; indikace HRT: obtížný klimakterický syndrom (návaly, urogenitální atrofie), hypogonadismus, kontracepce."),
   ("⛔", "Kontraindikace", True, "Prodělaná trombóza, hormonálně dependentní nádor, nejasné děložní krvácení, těžké jaterní onemocnění."),
   ("🛡️", "Gestagen", False, "Medroxyprogesteron, dydrogesteron, drospirenon, levonorgestrel — v kontracepci, v HRT jako OCHRANA endometria, u endometriózy a dysfunkčního krvácení."),
   ("🔀", "Tamoxifen", True, "SERM — antagonista v prsu, ale AGONISTA v endometriu, odtud riziko karcinomu endometria."),
   ("💊", "Raloxifen a anastrozol", False, "Raloxifen u osteoporózy; inhibitory aromatázy (anastrozol) u karcinomu prsu.")],
  "Gestagen v HRT není přidán kvůli účinku na příznaky, ale výhradně k ochraně endometria — proto po hysterektomii odpadá.")

S("121", "Kontraceptiva",
  "TŘI ZÁMKY NARAZ — zastavená ovulace, hustý hlen a nepřipravené endometrium.", "pokoj",
  [("🥚", "Zastavená ovulace", False, "Negativní zpětná vazba na FSH a LH potlačí ovulaci."),
   ("🍯", "Hustý hlen", False, "Zahuštění cervikálního hlenu, který je neprostupný pro spermie."),
   ("🛏️", "Nepřipravené endometrium", False, "Změna endometria nevhodná pro nidaci."),
   ("🩸", "Trombembolie", True, "Hlavní riziko kombinované kontracepce (ethinylestradiol + gestagen); dále infarkt a cévní mozková příhoda. Riziko je nejvyšší v prvním roce."),
   ("🚬", "Kouření nad 35 let", True, "Kontraindikace: prodělaná trombóza nebo trombofilie, kouření u ženy nad 35 let, migréna s aurou, nekontrolovaná hypertenze, karcinom prsu, těžké jaterní onemocnění."),
   ("🌼", "Třezalka a rifampicin", True, "Induktory CYP450 snižují účinnost; totéž průjem a zvracení do několika hodin po tabletě."),
   ("🍼", "Gestagenní formy", False, "Minipilulka, depotní injekce, implantát a nitroděložní systém neobsahují estrogen — vhodné při kojení a při kontraindikaci estrogenů; typicky nepravidelné špinění.")],
  "Nouzová kontracepce (levonorgestrel do 72 h, ulipristal-acetát do 120 h) ODKLÁDÁ OVULACI — nepůsobí abortivně a na již probíhající graviditu nemá vliv.")

S("122", "Farmakoterapie benigní hyperplazie prostaty",
  "DVĚ SLOŽKY POTÍŽÍ — svalové napětí (rychle) a objem žlázy (pomalu).", "pokoj",
  [("⚡", "α-blokátor", False, "Tamsulosin, silodosin (uroselektivní), doxazosin, terazosin, alfuzosin relaxují hladký sval prostaty a hrdla — úleva během DNÍ. Objem prostaty neovlivní."),
   ("🛏️", "První dávka na noc", True, "Ortostatická hypotenze a závrať — proto se první dávka podává na noc."),
   ("👁️", "IFIS", True, "Peroperační syndrom plovoucí duhovky — před operací katarakty je nutné oftalmologa upozornit. Dále retrográdní ejakulace u tamsulosinu."),
   ("🐢", "Finasterid", False, "Inhibitory 5-α-reduktázy blokují přeměnu testosteronu na dihydrotestosteron, čímž prostatu SKUTEČNĚ ZMENŠUJÍ a snižují riziko akutní retence moči a operace. Účinek za 3–6 MĚSÍCŮ."),
   ("📉", "PSA na polovinu", True, "Inhibitory 5-α-reduktázy snižují PSA přibližně na polovinu — nutné zohlednit při screeningu karcinomu."),
   ("🤰", "Teratogenita", True, "Kontraindikované u žen v reprodukčním věku; dále poruchy erekce, pokles libida, gynekomastie."),
   ("💊", "Kombinace", False, "Obě skupiny dohromady jsou účinnější u velké prostaty; dále tadalafil a mirabegron či anticholinergika při dráždivých příznacích.")],
  "Anticholinergikum u pacienta s hyperplazií prostaty může vyvolat akutní retenci moči — proto se přidává až po zajištění odtoku α-blokátorem.")

S("123", "Cytostatika",
  "ŽNĚ, KTERÉ NEROZLIŠUJÍ — poseká se nádor i dřeň, sliznice a vlasy.", "krajina",
  [("⚔️", "Kosa bez výběru", True, "Nízká selektivita — postihují i zdravé rychle proliferující tkáně: kostní dřeň, sliznice a vlasové folikuly. Podávají se v kombinačních režimech a v CYKLECH s pauzou na regeneraci dřeně."),
   ("💧", "Cyklofosfamid", True, "Alkylační látka; působí HEMORAGICKOU CYSTITIDU (metabolit akrolein) — prevence MESNOU a hydratací."),
   ("👂", "Cisplatina", True, "Nefrotoxická, ototoxická a silně emetogenní."),
   ("🍀", "Metotrexát", False, "Inhibitor dihydrofolátreduktázy — záchranná léčba LEUKOVORINEM. Dále 5-fluorouracil, cytarabin, 6-merkaptopurin."),
   ("❤️", "Doxorubicin", True, "Interkaluje do DNA a inhibuje topoizomerázu II; typická je KUMULATIVNÍ kardiomyopatie — sleduje se celková dávka, chrání dexrazoxan."),
   ("🫁", "Bleomycin", True, "Působí plicní fibrózu. Vinkristin je neurotoxický, taxany stabilizují mikrotubuly."),
   ("🌡️", "Febrilní neutropenie", True, "Myelosuprese (G-CSF), mukozitida a stomatitida, nauzea a zvracení (setrony, aprepitant, dexametazon), alopecie, neplodnost, syndrom nádorového rozpadu (hydratace, allopurinol, rasburikáza), sekundární malignity.")],
  "Toxicita je u každého cytostatika jiná a specifická — proto se kombinují látky, jejichž nežádoucí účinky se nepřekrývají.")

S("124", "Farmakoterapie anemií",
  "TŘI RŮZNÉ ANEMIE, TŘI RŮZNÉ LÉKY — a železo naslepo škodí.", "pokoj",
  [("🍊", "Železo s vitaminem C", False, "Vstřebává se dvojmocné Fe²⁺ v duodenu — nalačno, vstřebávání zlepšuje kyselina askorbová."),
   ("🥛", "Mléko a čaj", True, "Čaj, káva, mléko, antacida, inhibitory protonové pumpy a tetracykliny vstřebávání ZHORŠUJÍ."),
   ("⚫", "Černá stolice", True, "Nežádoucí: zácpa, nauzea a černá stolice — nezaměnit s melénou."),
   ("📅", "Tři měsíce navíc", False, "Léčba pokračuje ještě 3 měsíce po úpravě hemoglobinu, aby se doplnily zásoby (ferritin)."),
   ("⚠️", "Folát bez B12", True, "Před podáním kyseliny listové je nutné VYLOUČIT deficit B12 — folát upraví krevní obraz, ale neurologické poškození (funikulární myelóza) dál progreduje."),
   ("💉", "Perniciózní anemie", False, "B12 se podává parenterálně, zpravidla doživotně (chybí vnitřní faktor)."),
   ("🫘", "Erytropoetin", True, "U renální anemie — nutná zásoba železa, riziko hypertenze a trombóz. Hemolytické anemie: kortikosteroidy. Srpkovitá anemie: hydroxyurea. Otrava železem u dětí: deferoxamin.")],
  "Anemie se nikdy neléčí naslepo — podávat železo u anemie z jiné příčiny nejen nepomůže, ale škodí.")

S("125", "Rtg kontrastní látky",
  "DVĚ LÁTKY, DVA ZÁKAZY — jodová u ledvin a štítné žlázy, baryová u perforace.", "laborator",
  [("☢️", "Pozitivní a negativní", False, "Kontrastní látky nemají léčebný účinek — mění absorpci záření. Pozitivní pohlcují víc (jod, baryum), negativní jsou plyny."),
   ("💧", "Nefropatie", True, "Kontrastem indukovaná nefropatie — prevencí je dostatečná hydratace a vysazení nefrotoxických léků."),
   ("😰", "Anafylaktoidní reakce", True, "Nevyžaduje předchozí expozici; u rizikových premedikace kortikoidy a antihistaminiky. Neionické (nízkoosmolární) jsou dnes standardem a snášejí se lépe."),
   ("🛑", "Metformin", True, "Vysazuje se před podáním jodové látky u snížené funkce ledvin pro riziko laktátové acidózy."),
   ("🦋", "Štítná žláza", True, "Jodová látka blokuje vychytávání radiojodu a může vyvolat tyreotoxikózu — před plánovanou scintigrafií se nepodává."),
   ("⚠️", "Baryum a perforace", True, "Síran barnatý je KONTRAINDIKOVÁN při podezření na perforaci — únik vyvolá těžkou peritonitidu či mediastinitidu; volí se vodná jodová látka."),
   ("🧲", "Gadolinium", True, "Patří k magnetické rezonanci, nikoli k rentgenu — při těžké renální insuficienci nefrogenní systémová fibróza.")],
  "Anafylaktoidní reakce na kontrastní látku není klasická alergie zprostředkovaná IgE — proto může vzniknout i při prvním podání.")

S("126", "Léčiva pro místní účinek na kůži, dezinficiencia",
  "KOŽNÍ AMBULANCE S PRAVIDLEM — VLHKÉ NA VLHKÉ, MASTNÉ NA SUCHÉ.", "pokoj",
  [("💧", "Obklad na mokvání", False, "Na mokvající zánět obklady, roztoky a krémy."),
   ("🧈", "Mast na suchou kůži", False, "Na suchou a lichenifikovanou kůži masti, které účinek zesilují okluzí; gely vysychají a chladí, zásypy vysušují."),
   ("⚠️", "Atrofie kůže", True, "Lokální kortikoidy (čtyři třídy podle síly, hydrokortison až klobetasol) dlouhodobě působí atrofii, strie, teleangiektazie, periorální dermatitidu a kandidózu."),
   ("👤", "Obličej a záhyby", True, "Tam patří jen slabé přípravky a krátce — vstřebávají se nejvíc. Alternativou jsou inhibitory kalcineurinu (takrolimus, pimekrolimus), které kůži neatrofují."),
   ("🧴", "Emoliencia", False, "Základ péče u atopické dermatitidy; dále keratolytika (kyselina salicylová, močovina), antimykotika, mupirocin (omezeně kvůli rezistenci), retinoidy (adapalen — teratogenní)."),
   ("🟤", "Povidon-jod", False, "Široké spektrum včetně spor."),
   ("👂", "Chlorhexidin", True, "Dlouhý reziduální účinek, ale je OTOTOXICKÝ a NEUROTOXICKÝ — nesmí k oku ani do ucha při perforaci. Alkoholy (70 %) nepůsobí na spory a nepatří na otevřenou ránu; peroxid vodíku poškozuje granulační tkáň; oktenidin je dobře snášený.")],
  "Silný kortikoid na velkou plochu a pod okluzí se vstřebá natolik, že může utlumit osu hypothalamus–hypofýza–nadledviny — lokální neznamená bez systémového rizika.")

S("127", "Infuzní terapie",
  "TŘI NÁDRŽE TĚLA — a glukóza, která nedoplní ani jednu z těch správných.", "more",
  [("🧂", "Balancovaný roztok", False, "Krystaloidy volně procházejí kapilární stěnou; izotonické (Ringerův, Hartmannův, Plasmalyte, fyziologický roztok) doplňují extracelulární prostor — léčba volby u hypovolemie a dehydratace."),
   ("⚗️", "Hyperchloremická acidóza", True, "Fyziologický roztok má nefyziologicky vysoký obsah chloridů; ve velkých objemech působí hyperchloremickou metabolickou acidózu — proto se dnes upřednostňují balancované roztoky."),
   ("🍬", "Glukóza 5 %", True, "Izotonická jen v lahvi — po metabolizaci cukru zůstane VOLNÁ VODA, která se rozdělí do celkové tělesné vody. K doplnění objemu se NEHODÍ."),
   ("🧠", "Hypertonický roztok", True, "NaCl 3 % a manitol táhnou vodu z buněk — u nitrolební hypertenze a těžké hyponatremie."),
   ("🐢", "Pomalá korekce", True, "Hyponatremie se koriguje POMALU — rychlá úprava hrozí osmotickou demyelinizací."),
   ("⛔", "Hydroxyethylškrob", True, "Dnes se nepoužívá pro poškození ledvin a zvýšenou mortalitu u kritických nemocných; z koloidů zůstává albumin a želatina."),
   ("🍽️", "Parenterální výživa", True, "Glukóza, aminokyseliny, tuky, elektrolyty, stopové prvky a vitaminy centrálním katétrem — hrozí refeeding syndrom a infekce katétru.")],
  "Volba roztoku vychází z toho, který prostor je třeba doplnit — nitrocévní, extracelulární, nebo celkovou tělesnou vodu.")

S("128", "Vitaminy rozpustné v tucích",
  "SPÍŽ, KTERÁ SE PLNÍ — A, D, E, K se ukládají, a proto se dají i předávkovat.", "pokoj",
  [("🧈", "Tuk a žluč", True, "Vstřebávají se s tuky za přítomnosti žluči a ukládají se v játrech a tukové tkáni. Při poruše trávení tuků (cholestáza, pankreatická insuficience, celiakie, orlistat, parafinový olej) vzniká deficit."),
   ("👁️", "Šeroslepost", False, "Vitamin A (retinol) — zrak (rodopsin), diferenciace epitelu, imunita. Deficit: šeroslepost, xeroftalmie, keratomalacie."),
   ("🤰", "Retinoidy", True, "Nadbytek vitaminu A: bolest hlavy, nitrolební hypertenze, hepatotoxicita a silná TERATOGENITA — isotretinoin je v graviditě kontraindikován a vyžaduje spolehlivou kontracepci."),
   ("🦴", "Křivice", False, "Vitamin D se aktivuje hydroxylací v játrech (25-OH) a v ledvinách (1,25-OH, kalcitriol); zvyšuje vstřebávání vápníku a fosfátů. Deficit: křivice u dětí, osteomalacie u dospělých."),
   ("🧂", "Hyperkalcemie", True, "Nadbytek vitaminu D — hyperkalcemie s nefrokalcinózou a zvracením."),
   ("🛡️", "Vitamin E", False, "Hlavní lipofilní antioxidant; deficit vede k hemolýze a neuropatii, vysoké dávky zvyšují riziko krvácení."),
   ("🩸", "Vitamin K", False, "Kofaktor γ-karboxylace faktorů II, VII, IX a X a proteinů C a S — antidotum warfarinu; podává se novorozencům v prevenci krvácivé nemoci.")],
  "Deficit vitaminů rozpustných v tucích je typickou komplikací dlouhodobé cholestázy a bariatrických operací — proto se tam substituují cíleně.")

S("129", "Vitaminy rozpustné ve vodě",
  "PROTÉKAJÍCÍ SPÍŽ — co se nespotřebuje, odteče močí. Zásoba drží jen u B12.", "pokoj",
  [("🍺", "Thiamin před glukózou", True, "B1 je koenzym dekarboxyláz. Deficit u alkoholismu a malnutrice: beri-beri a WERNICKEOVA ENCEFALOPATIE (zmatenost, ataxie, oftalmoplegie) až Korsakovův syndrom — thiamin se podává VŽDY PŘED GLUKÓZOU."),
   ("👄", "Riboflavin", False, "B2 — cheilitida, angulární stomatitida, glositida."),
   ("🌽", "Pelagra", False, "B3 (niacin) — dermatitida, průjem, demence; ve vysokých dávkách snižuje lipidy a vyvolává flush."),
   ("💊", "Pyridoxin a izoniazid", True, "B6 je koenzym transamináz; deficit vzniká při léčbě IZONIAZIDEM a projeví se periferní neuropatií a křečemi — proto se izoniazid podává s pyridoxinem. Vysoké dávky samy neuropatii způsobují."),
   ("🧬", "Folát a B12", True, "Nutné pro syntézu DNA; deficit působí megaloblastovou anemii. B12 navíc chrání myelin — deficit vede k funikulární myelóze. Folát až po vyloučení deficitu B12."),
   ("🤰", "Prevence rozštěpů", False, "Kyselina listová se podává preventivně v graviditě proti rozštěpům neurální trubice."),
   ("🦷", "Skorbut", False, "Vitamin C je nutný pro hydroxylaci kolagenu; deficit působí krvácení dásní, viklavost zubů, špatné hojení a petechie. Zlepšuje vstřebávání železa.")],
  "B12 má v játrech zásobu na roky — proto se jeho deficit projeví až po dlouhé době, na rozdíl od ostatních vitaminů skupiny B.")

S("130", "Farmakoterapie osteoporózy",
  "SKLENICE VODY A ZÁKAZ LEHNOUT — a před léčbou se sanuje chrup.", "pokoj",
  [("💧", "Velká sklenice vody", True, "Perorální bisfosfonát se užívá nalačno, zapíjí VELKOU SKLENICÍ ČISTÉ VODY a půl hodiny se NELEHÁ — jinak hrozí erozivní ezofagitida."),
   ("🦴", "Apoptóza osteoklastů", False, "Alendronát, risedronát, kyselina zoledronová se vážou na hydroxyapatit — lék první volby. Cílem je snížit riziko ZLOMENINY, ne jen zvýšit denzitu."),
   ("🦷", "Osteonekróza čelisti", True, "Vzácný, ale závažný nežádoucí účinek — riziko stoupá u nitrožilního podání, po extrakci zubu a u nádorových indikací; dále atypické zlomeniny femuru."),
   ("🫘", "Kontraindikace", True, "Těžká renální insuficience a hypokalcemie, kterou je nutné napravit před zahájením."),
   ("💉", "Denosumab", False, "Monoklonální protilátka proti RANKL — brání zrání osteoklastů; podkožně jednou za půl roku, vhodný i při renální insuficienci."),
   ("⛔", "Nepřerušit denosumab", True, "Po vysazení dochází k rychlé ztrátě kosti a riziku mnohočetných obratlových zlomenin — nesmí se přerušit bez navazující léčby."),
   ("🚀", "Teriparatid", False, "Analog parathormonu — v PULZNÍM podání kost TVOŘÍ, na rozdíl od trvale zvýšeného PTH, který ji odbourává; dále romosozumab. Raloxifen chrání kost, ale zvyšuje riziko trombózy.")],
  "Základem je vždy dostatečný příjem vápníku a vitaminu D, pohyb a prevence pádů — bez nich ostatní léky nefungují.")

S("131", "Fytoterapie",
  "BYLINKÁŘSKÁ ZAHRADA S VAROVÁNÍM — rostlinné neznamená neškodné.", "les",
  [("🌼", "Třezalka", True, "Silný INDUKTOR CYP3A4 a P-glykoproteinu — snižuje účinnost hormonální kontracepce, warfarinu, cyklosporinu, digoxinu a antiretrovirotik; s antidepresivy hrozí serotoninový syndrom."),
   ("🍇", "Grapefruit", True, "Není fytoterapeutikum, ale silný INHIBITOR CYP3A4 — zvyšuje hladiny statinů, blokátorů kalciových kanálů a imunosupresiv. Působí přesně opačně než třezalka."),
   ("🩸", "Ginkgo a česnek", True, "Zvyšují riziko krvácení v kombinaci s antikoagulancii a antiagregancii."),
   ("⚗️", "Standardizace", False, "Formy: droga, nálev (infusum), odvar (decoctum), tinktura, silice, standardizovaný extrakt. Bez standardizace na obsah účinné látky se dávka mezi šaržemi liší."),
   ("😴", "Kozlík a meduňka", False, "Nespavost a úzkost; echinacea (imunomodulace), silymarin (játra), heřmánek a šalvěj (kloktadla)."),
   ("🌿", "Máta a senna", False, "Máta a fenykl spasmolyticky; senna a řešetlák jsou stimulační projímadla; brusinka v prevenci močových infekcí; serenoa u hyperplazie prostaty."),
   ("🤰", "Gravidita", True, "Řada rostlin je v graviditě kontraindikována.")],
  "Účinnost je u většiny fytofarmak doložena slabě — jejich hlavní klinický význam bývá spíš v interakcích než v léčebném přínosu.")

S("132", "Obecná toxikologie",
  "PARACELSOVY VÁHY — dávka dělá jed. Rozdíl mezi lékem a jedem je kvantitativní.", "laborator",
  [("⚖️", "Váhy", False, "Každá látka je při dostatečné dávce toxická. Toxicita je vlastnost látky, expozice kontakt s ní, riziko pravděpodobnost poškození za dané expozice."),
   ("💀", "LD50", False, "Dávka usmrcující polovinu pokusných zvířat — čím nižší, tím toxičtější látka."),
   ("📏", "Terapeutický index", True, "TI = TD50 ÷ ED50; léčiva s úzkým indexem (digoxin, warfarin, theofylin, lithium, aminoglykosidy) vyžadují monitorování hladin."),
   ("🔄", "Letální syntéza", True, "Biotransformace může látku detoxikovat, ale i AKTIVOVAT: methanol → kyselina mravenčí, paracetamol → NAPQI, ethylenglykol → oxaláty."),
   ("⏳", "Akutní a chronické", False, "Akutní otrava (jednorázová vysoká dávka) × chronická (dlouhodobá nízká expozice s kumulací — olovo, rtuť). Podle úmyslu náhodné, sebevražedné, profesní a zneužití."),
   ("🧬", "Zvláštní formy", False, "Toxicita může být místní nebo systémová, vratná či nevratná; zvláštními formami jsou kancerogenita, mutagenita a teratogenita."),
   ("💊", "Antidotum", True, "Působí specificky (protilátky, chelátory, kompetice o enzym či receptor) nebo nespecificky — ale existuje jen pro menšinu jedů.")],
  "Toxikokinetika popisuje osud jedu stejně jako farmakokinetika osud léku — vstřebání, distribuci, biotransformaci a vylučování.")

S("133", "Terapie otrav a předávkování",
  "POŘADÍ, KTERÉ SE NEMĚNÍ — nejdřív vitální funkce, teprve pak jed.", "pokoj",
  [("🫁", "ABC", True, "Zajištění dýchacích cest, dýchání a oběhu má absolutní přednost. PODPŮRNÁ LÉČBA ZACHRÁNÍ VÍC ŽIVOTŮ NEŽ ANTIDOTUM."),
   ("⚫", "Aktivní uhlí", True, "1 g/kg, hlavní metoda při požití, účinné především do 1 hodiny. NEVÁŽE alkoholy, kovy, železo, lithium, kyseliny a louhy."),
   ("🚫", "Zákaz zvracení", True, "Vyvolávání zvracení se nedoporučuje (riziko aspirace), výplach žaludku se provádí zcela výjimečně."),
   ("🧪", "Žíraviny", True, "Nesmí se vyvolat zvracení ani neutralizovat — hrozí druhé poleptání a perforace."),
   ("💧", "Alkalizace moči", False, "Bikarbonátem u salicylátů a barbiturátů; hemodialýza u methanolu, ethylenglykolu, lithia, salicylátů a metforminu."),
   ("💊", "Antidota I", False, "Naloxon (opioidy) · flumazenil (benzodiazepiny, opatrně) · N-acetylcystein (paracetamol) · atropin + pralidoxim (organofosfáty) · fomepizol nebo ethanol (methanol, ethylenglykol)."),
   ("💉", "Antidota II", False, "Vitamin K a protrombinový komplex (warfarin) · protamin (heparin) · kyslík (oxid uhelnatý) · hydroxokobalamin (kyanidy) · deferoxamin (železo) · Fab protilátky (digoxin) · glukagon (β-blokátory) · kalcium a inzulin (blokátory kalciových kanálů) · chelátory (těžké kovy).")],
  "Vždy je namístě kontaktovat Toxikologické informační středisko — u vzácných jedů rozhoduje aktuální doporučení, ne paměť.")

S("134", "Toxikologie rostlin a hub",
  "LES, KDE ROZHODUJE LATENCE — čím déle nic, tím hůř.", "les",
  [("⏱️", "Krátká latence", False, "Do 4 hodin — zpravidla jen gastrointestinální obtíže. Muchomůrka červená a tygrovaná (kyselina ibotenová a muscimol — opilost, delirium, halucinace)."),
   ("💧", "Muskarin", True, "Strmělky a vláknice — muskarinový syndrom: slinění, slzení, pocení, mióza, průjem, bradykardie. Antidotem ATROPIN."),
   ("🍺", "Hnojník inkoustový", False, "Coprin působí disulfiramovou reakci po alkoholu."),
   ("💀", "Muchomůrka zelená", True, "Latence 6–24 hodin. Amanitiny blokují RNA-polymerázu II; po asymptomatickém intervalu prudká gastroenteritida, ZDÁNLIVÉ ZLEPŠENÍ a poté SELHÁNÍ JATER. Léčba podpůrná, silibinin a penicilin G, případně transplantace."),
   ("🫘", "Pavučinec plyšový", True, "Orellanin poškozuje ledviny s latencí i několika dnů."),
   ("💓", "Náprstník a oleandr", True, "Digitalisové glykosidy — arytmie; antidotem Fab protilátky. Dále konvalinka a tis červený (taxiny, arytmie, bez antidota)."),
   ("🥀", "Rulík a durman", True, "Atropin a skopolamin — anticholinergní delirium, mydriáza, suchá horká kůže; antidotem FYSOSTIGMIN. Bolehlav (koniin — obrna dýchacích svalů), ricin, bolševník (fototoxická dermatitida).")],
  "Zdánlivé zlepšení po gastroenteritidě u muchomůrky zelené je zrádné — právě v této fázi probíhá jaterní poškození, které se projeví až za další den.")

S("135", "Toxikologie živočišných jedů",
  "LOUKA S JEDOVATÝMI OBYVATELI — a nejčastěji zabíjí ne jed, ale ANAFYLAXE.", "les",
  [("🐝", "Včela a vosa", True, "Nejčastější hrozbou v našich podmínkách je ANAFYLAKTICKÁ REAKCE — lékem první volby je ADRENALIN i.m.; alergik má u sebe adrenalinové pero."),
   ("👄", "Bodnutí v ústech", True, "Nebezpečná jsou bodnutí v dutině ústní a hltanu — edém dýchacích cest. Včelí žihadlo se vytahuje, nemačká."),
   ("🐍", "Zmije obecná", False, "Jediný jedovatý had v ČR; jed je převážně hemotoxický a cytotoxický — bolestivý otok, hematom, porucha srážlivosti, hypotenze, zvracení. Úmrtí je vzácné."),
   ("🚫", "Zákazy první pomoci", True, "NEVYSÁVAT ránu, neřezat, nepřikládat škrtidlo ani led. Znehybnit končetinu, klid, transport; u těžkých případů antisérum."),
   ("🌍", "Exotičtí hadi", False, "Kobry a mamby působí neurotoxicky (obrna dýchacích svalů), zmijovití hemotoxicky."),
   ("🕷️", "Černá vdova", True, "Latrotoxin — masivní výlev acetylcholinu, svalové křeče a bolest břicha."),
   ("🐟", "Mořští živočichové", True, "Medúzy (nematocysty), rejnok a ropušnice (termolabilní jed — ponoření do horké vody), tetrodotoxin (fugu) blokuje sodíkové kanály a vede k obrně dýchání. Klíště přenáší boreliózu a klíšťovou encefalitidu, samo jedovaté není.")],
  "Adrenalinové pero se aplikuje do stehna přes oděv a co nejdříve — odklad je nejčastější příčinou úmrtí na anafylaxi po bodnutí hmyzem.")

S("136", "Intoxikace sloučeninami rtuti, arzenu a olova",
  "STARÁ HUŤ — kovy se vážou na –SH skupiny, kumulují se a otrava je většinou CHRONICKÁ.", "laborator",
  [("🔗", "Sulfhydrylové skupiny", False, "Kovy se vážou na –SH skupiny bílkovin a inaktivují enzymy; v těle se kumulují. Léčbou je přerušení expozice a chelatační činidla."),
   ("🩸", "Bazofilní tečkování", True, "OLOVO blokuje enzymy syntézy hemu (δ-aminolevulinátdehydratáza a ferrochelatáza) — mikrocytární anemie s bazofilním tečkováním erytrocytů."),
   ("✋", "Přepadávající ruka", True, "Olověná kolika, obstipace, periferní neuropatie, u dětí encefalopatie a trvalé snížení intelektu; olověný lem na dásních. Chelátory: EDTA, sukcimer, dimerkaprol."),
   ("🐟", "Methylrtuť", True, "Nejtoxičtější organická forma — prochází hematoencefalickou i placentární bariérou a hromadí se v potravním řetězci ryb (Minamata): poruchy zraku, sluchu, ataxie, poškození plodu."),
   ("💨", "Páry rtuti", True, "Elementární rtuť je nebezpečná INHALACÍ par (pneumonitida, třes, erethismus, gingivitida a slinění), zatímco požitá se téměř nevstřebá. Chelátory: DMPS, sukcimer, penicilamin."),
   ("💅", "Meesovy proužky", True, "ARZEN blokuje pyruvátdehydrogenázu. Chronicky hyperkeratóza dlaní, hyperpigmentace, Meesovy proužky na nehtech, polyneuropatie a karcinom kůže, plic a močového měchýře."),
   ("🧄", "Česneková pachuť", False, "Akutně prudká gastroenteritida (rýžovité stolice), hypotenze a arytmie; v dechu bývá česneková pachuť. Chelátory: dimerkaprol (BAL), DMPS, sukcimer.")],
  "Chelatační léčba není bez rizika — chelátory vážou i esenciální kovy (zinek, měď) a samy mohou být nefrotoxické, proto se podávají cíleně a pod kontrolou.")
